// Hash executable simulation dependencies rather than every source file in their directories.
// Types, comments and presentation-only modules cannot change the simulation runtime.
//
// The manifest is a build artifact: it is git-ignored and regenerated by the npm pre-hooks of
// every script that reads it (start, build, test, sim, typecheck), so branches never conflict on it.
const fs = require("fs");
const path = require("path");
const crypto = require("crypto");
const ts = require("typescript");
const { builtinModules } = require("module");

const root = path.resolve(__dirname, "..");
const output = "src/data/RunCompatibility.json";
const rulesRevision = 2;
const sourceExtension = /\.(?:[cm]?[jt]sx?|json)$/;
const productionSource = (file) =>
  sourceExtension.test(file) && !/\.(test|spec)\./.test(file);

function filesUnder(directory) {
  return fs
    .readdirSync(path.join(root, directory), { withFileTypes: true })
    .flatMap((entry) => {
      const relative = `${directory}/${entry.name}`;
      return entry.isDirectory() ? filesUnder(relative) : [relative];
    });
}

function readInput(file) {
  const raw = fs.readFileSync(path.join(root, file));
  if (
    raw
      .subarray(0, 80)
      .toString()
      .startsWith("version https://git-lfs.github.com/spec/")
  ) {
    throw new Error(
      `Fetch the actual input before generating compatibility: ${file}`,
    );
  }
  // Git checkouts on different platforms must produce the same content identity.
  const content = file.endsWith(".bin")
    ? raw
    : Buffer.from(raw.toString("utf8").replace(/\r\n/g, "\n"));
  return {
    raw,
    content,
    inputDigest: crypto.createHash("sha256").update(content).digest("hex"),
  };
}

const sourceFiles = ["src/data", "src/helpers", "src/reducers"]
  .flatMap(filesUnder)
  .filter((file) => productionSource(file) && file !== output);
const dataFiles = filesUnder("public/data").filter((file) =>
  /\.(bin|csv|json)$/.test(file),
);
const sourceInputs = [
  "src/Constants.tsx",
  "src/Types.tsx",
  "package-lock.json",
  ...sourceFiles,
  ...dataFiles,
].sort();
const sourceDigest = crypto.createHash("sha256");
const dataIntegrity = {};
sourceDigest.update(`electrify-source:${rulesRevision}\n`);
for (const file of sourceInputs) {
  const { raw, content, inputDigest } = readInput(file);
  sourceDigest.update(`${file}\0${inputDigest}\n`);
  if (file.startsWith("public/data/")) {
    // Integrity checks consume raw HTTP bytes, so shipped text must have the
    // same LF line endings enforced by .gitattributes on every build platform.
    if (!file.endsWith(".bin") && !raw.equals(content)) {
      throw new Error(`Normalize shipped data to LF before building: ${file}`);
    }
    dataIntegrity[file.slice("public".length)] =
      `sha256-${Buffer.from(inputDigest, "hex").toString("base64")}`;
  }
}

// Scenario definitions hold React prompts. Their rendering cannot affect the reducer; do not
// follow those imports into the application. The importing module (including its JSX, tutorial
// conditions and import path) remains fingerprinted. Unknown dependencies elsewhere are included.
const presentationOnly = new Set([
  "src/components/base/TutorialPrompt.tsx",
  "src/components/base/CustomerGrowthChallenge.tsx",
]);
const externalPackages = new Set();
const runtimeInputs = new Map();
const packageName = (specifier) =>
  specifier
    .split("/")
    .slice(0, specifier.startsWith("@") ? 2 : 1)
    .join("/");
const printer = ts.createPrinter({ removeComments: true });

function runtimeSource(file) {
  const { content } = readInput(file);
  const result = ts.transpileModule(content.toString("utf8"), {
    fileName: file,
    reportDiagnostics: true,
    compilerOptions: {
      target: ts.ScriptTarget.ES2022,
      module: ts.ModuleKind.ESNext,
      jsx: ts.JsxEmit.React,
      removeComments: true,
    },
  });
  const error = result.diagnostics?.find(
    (diagnostic) => diagnostic.category === ts.DiagnosticCategory.Error,
  );
  if (error)
    throw new Error(
      `Cannot fingerprint ${file}: ${ts.flattenDiagnosticMessageText(error.messageText, " ")}`,
    );
  const parsed = ts.createSourceFile(
    file.replace(/\.[^.]+$/, ".js"),
    result.outputText,
    ts.ScriptTarget.ES2022,
    true,
    ts.ScriptKind.JS,
  );
  // The printer normalizes formatting; rebuild string literals so quote choice is irrelevant too.
  const transformed = ts.transform(parsed, [
    (context) => {
      const visit = (node) =>
        ts.isStringLiteral(node)
          ? ts.factory.createStringLiteral(node.text)
          : ts.visitEachChild(node, visit, context);
      return (node) => ts.visitNode(node, visit);
    },
  ]);
  const canonical = printer.printFile(transformed.transformed[0]);
  transformed.dispose();
  return { parsed, canonical };
}

function followImport(from, specifier) {
  if (!specifier.startsWith(".")) {
    if (!builtinModules.includes(specifier) && !specifier.startsWith("node:"))
      externalPackages.add(packageName(specifier));
    return;
  }
  const base = path.posix.normalize(
    path.posix.join(path.posix.dirname(from), specifier),
  );
  // Runtime integrity readers import this generated output. Bootstrap without requiring an
  // existing manifest, and never feed its previous contents back into its own identity.
  if (base === output) return;
  if (!base.startsWith("src/"))
    throw new Error(`Simulation import leaves src: ${from}: ${specifier}`);
  const file = [
    base,
    ...[
      ".ts",
      ".tsx",
      ".js",
      ".jsx",
      ".cjs",
      ".mjs",
      ".json",
      "/index.ts",
      "/index.tsx",
      "/index.js",
    ].map((extension) => base + extension),
  ].find(
    (candidate) =>
      fs.existsSync(path.join(root, candidate)) &&
      fs.statSync(path.join(root, candidate)).isFile(),
  );
  if (!file)
    throw new Error(`Unresolved simulation import: ${from}: ${specifier}`);
  visitRuntime(file);
}

function visitRuntime(file) {
  if (file === output || presentationOnly.has(file) || runtimeInputs.has(file))
    return;
  if (file.endsWith(".json")) {
    runtimeInputs.set(
      file,
      JSON.stringify(JSON.parse(readInput(file).content.toString("utf8"))),
    );
    return;
  }
  if (!sourceExtension.test(file))
    throw new Error(`Unsupported simulation input: ${file}`);
  const { parsed, canonical } = runtimeSource(file);
  runtimeInputs.set(file, canonical);
  const visit = (node) => {
    if (
      (ts.isImportDeclaration(node) || ts.isExportDeclaration(node)) &&
      node.moduleSpecifier
    ) {
      followImport(file, node.moduleSpecifier.text);
    } else if (
      ts.isCallExpression(node) &&
      (node.expression.kind === ts.SyntaxKind.ImportKeyword ||
        (ts.isIdentifier(node.expression) &&
          node.expression.text === "require"))
    ) {
      const argument = node.arguments[0];
      if (!argument || !ts.isStringLiteral(argument))
        throw new Error(
          `Nonliteral simulation import in ${file}; declare its dependencies explicitly`,
        );
      followImport(file, argument.text);
    }
    ts.forEachChild(node, visit);
  };
  visit(parsed);
}

visitRuntime("src/reducers/Game.tsx");
for (const file of [...runtimeInputs.keys()].sort()) {
  if (!sourceInputs.includes(file))
    sourceDigest.update(`${file}\0${readInput(file).inputDigest}\n`);
}
const sourceId = `source-${rulesRevision}-${sourceDigest.digest("hex")}`;

// A dev-tool or unrelated UI dependency bump must not split official runs. Retain the installed
// versions/integrities of all runtime packages actually imported by the simulation and their
// transitive dependencies (including installed optional/peer dependencies).
const lock = JSON.parse(
  readInput("package-lock.json").content.toString("utf8"),
);
const packages = lock.packages;
if (!packages || lock.lockfileVersion < 2)
  throw new Error("Simulation compatibility requires a packages lockfile");
const runtimePackages = new Map();
function followPackage(name, from = "", optional = false) {
  // Published @types dependencies describe APIs; their declarations are erased above. A direct
  // runtime import is still recorded, so a new executable use cannot disappear into this rule.
  if (from && name.startsWith("@types/")) return;
  let directory = from;
  let key;
  while (true) {
    const candidate = path.posix.join(directory, "node_modules", name);
    if (packages[candidate]) {
      key = candidate;
      break;
    }
    if (!directory) break;
    directory = path.posix.dirname(directory);
    if (directory === ".") directory = "";
  }
  if (!key) {
    if (optional) return;
    throw new Error(
      `Missing simulation dependency in lockfile: ${name} from ${from || "root"}`,
    );
  }
  if (runtimePackages.has(key)) return;
  const entry = packages[key];
  runtimePackages.set(key, {
    version: entry.version,
    integrity: entry.integrity,
  });
  for (const dependency of Object.keys(entry.dependencies || {}).sort())
    followPackage(dependency, key, !!entry.optionalDependencies?.[dependency]);
  for (const dependency of Object.keys(entry.optionalDependencies || {}).sort())
    followPackage(dependency, key, true);
  for (const dependency of Object.keys(entry.peerDependencies || {}).sort())
    followPackage(
      dependency,
      key,
      !!entry.peerDependenciesMeta?.[dependency]?.optional,
    );
}
for (const name of [...externalPackages].sort()) followPackage(name);

const digest = crypto.createHash("sha256");
digest.update(`electrify-rules:${rulesRevision}\n`);
for (const file of [...runtimeInputs.keys()].sort())
  digest.update(
    `${file}\0${crypto.createHash("sha256").update(runtimeInputs.get(file)).digest("hex")}\n`,
  );
for (const name of [...runtimePackages.keys()].sort())
  digest.update(`${name}\0${JSON.stringify(runtimePackages.get(name))}\n`);
for (const file of dataFiles.sort())
  digest.update(`${file}\0${readInput(file).inputDigest}\n`);
const compatibilityId = `rules-${rulesRevision}-${digest.digest("hex")}`;
// Package parsing and the installed library can change without changing official runs. Shared
// rules/compiler owners stay above, even when first introduced for community packages.
const modDigest = crypto.createHash("sha256");
modDigest.update(
  `electrify-mod-runtime:${rulesRevision}\n${compatibilityId}\n`,
);
for (const file of [
  ...filesUnder("src/mods").filter(productionSource),
  "electron/mods.cjs",
  "electron/steam-workshop.cjs",
].sort()) {
  modDigest.update(`${file}\0${readInput(file).inputDigest}\n`);
}
const modRuntimeId = `mod-${rulesRevision}-${modDigest.digest("hex")}`;
// Steam leaderboards are named after compatibilityId, so co-op transport and interface edits must
// not move it. Co-op lobbies and shared saves also require the same co-op code on every peer.
const multiplayerDigest = crypto.createHash("sha256");
multiplayerDigest.update(`${sourceId}\n${compatibilityId}\n${modRuntimeId}\n`);
for (const file of [
  ...filesUnder("src/multiplayer").filter(productionSource),
  "src/workers/Multiplayer.worker.ts",
  "electron/steam-multiplayer.cjs",
  "electron/coop-codec.cjs",
].sort()) {
  multiplayerDigest.update(`${file}\0${readInput(file).inputDigest}\n`);
}
const manifest = {
  rulesRevision,
  sourceId,
  compatibilityId,
  modRuntimeId,
  multiplayerCompatibilityId: `coop-${rulesRevision}-${multiplayerDigest.digest("hex")}`,
  dataIntegrity,
};
const serialized = `${JSON.stringify(manifest, null, 2)}\n`;
const destination = path.join(root, output);
// Skip an identical rewrite so parallel scripts never read a half-written file or churn mtimes.
const current = fs.existsSync(destination)
  ? fs.readFileSync(destination, "utf8")
  : "";
if (current !== serialized) {
  fs.writeFileSync(destination, serialized);
}
